-- LOCAL DISPOSABLE DATABASE ONLY. Minimal reproduction of observed live metadata.
-- Not a production dump: unrelated columns/FKs/triggers are deliberately omitted.
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
GRANT USAGE ON SCHEMA auth TO anon, authenticated;
CREATE TABLE public.classrooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, join_code text UNIQUE NOT NULL, created_by uuid NOT NULL);
CREATE TABLE public.classroom_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), classroom_id uuid REFERENCES public.classrooms ON DELETE CASCADE, user_id uuid NOT NULL, role text NOT NULL DEFAULT 'student' CHECK(role IN ('student','teacher')), UNIQUE(classroom_id,user_id));
CREATE TABLE public.trivia_groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, join_code text UNIQUE NOT NULL, is_public boolean DEFAULT true, created_by uuid NOT NULL);
CREATE TABLE public.trivia_group_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid REFERENCES public.trivia_groups ON DELETE CASCADE, user_id uuid NOT NULL, role text NOT NULL DEFAULT 'member' CHECK(role IN ('member','admin')), UNIQUE(group_id,user_id));
CREATE TABLE public.classroom_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), classroom_id uuid REFERENCES public.classrooms ON DELETE CASCADE, assigned_by uuid NOT NULL);
CREATE FUNCTION public.is_classroom_teacher(p_classroom_id uuid,p_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM classroom_members WHERE classroom_id=p_classroom_id AND user_id=p_user_id AND role='teacher') $$;
CREATE FUNCTION public.is_classroom_member(p_classroom_id uuid,p_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM classroom_members WHERE classroom_id=p_classroom_id AND user_id=p_user_id) $$;
CREATE FUNCTION public.is_group_member(p_group_id uuid,p_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM trivia_group_members WHERE group_id=p_group_id AND user_id=p_user_id) $$;
ALTER TABLE public.classrooms ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.classroom_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.trivia_groups ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.trivia_group_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.classroom_assignments ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO anon,authenticated;
CREATE POLICY classrooms_select ON public.classrooms FOR SELECT USING(created_by=auth.uid() OR is_classroom_member(id,auth.uid()));
CREATE POLICY classrooms_insert ON public.classrooms FOR INSERT WITH CHECK(created_by=auth.uid());
CREATE POLICY classrooms_update ON public.classrooms FOR UPDATE USING(created_by=auth.uid());
CREATE POLICY classrooms_delete ON public.classrooms FOR DELETE USING(created_by=auth.uid());
CREATE POLICY classroom_members_select ON public.classroom_members FOR SELECT USING(user_id=auth.uid() OR is_classroom_teacher(classroom_id,auth.uid()));
CREATE POLICY classroom_members_insert ON public.classroom_members FOR INSERT WITH CHECK(user_id=auth.uid());
CREATE POLICY classroom_members_delete ON public.classroom_members FOR DELETE USING(user_id=auth.uid() OR is_classroom_teacher(classroom_id,auth.uid()));
CREATE POLICY trivia_groups_select ON public.trivia_groups FOR SELECT USING(is_public=true OR created_by=auth.uid() OR is_group_member(id,auth.uid()));
CREATE POLICY trivia_groups_insert ON public.trivia_groups FOR INSERT WITH CHECK(created_by=auth.uid());
CREATE POLICY trivia_groups_update ON public.trivia_groups FOR UPDATE USING(created_by=auth.uid());
CREATE POLICY trivia_group_members_select ON public.trivia_group_members FOR SELECT USING(user_id=auth.uid() OR is_group_member(group_id,auth.uid()));
CREATE POLICY trivia_group_members_insert ON public.trivia_group_members FOR INSERT WITH CHECK(user_id=auth.uid());
CREATE POLICY trivia_group_members_delete ON public.trivia_group_members FOR DELETE USING(user_id=auth.uid());
CREATE POLICY "Members can read assignments" ON public.classroom_assignments FOR SELECT USING(auth.uid() IN (SELECT user_id FROM classroom_members WHERE classroom_members.classroom_id=classroom_assignments.classroom_id));
CREATE POLICY "Teachers can create assignments" ON public.classroom_assignments FOR INSERT WITH CHECK(auth.uid()=assigned_by);
